INSERT INTO `categories` (`id`, `wp_term_id`, `wp_taxonomy_id`, `name`, `slug`, `parent_id`, `description`, `count`) VALUES (1, 1, 1, 'Uncategorized', 'uncategorized', 0, '', 5);
INSERT INTO `categories` (`id`, `wp_term_id`, `wp_taxonomy_id`, `name`, `slug`, `parent_id`, `description`, `count`) VALUES (2, 61, 61, 'Tech', 'tech', 0, 'Discover the latest tech products designed to enhance your life. From cutting-edge smartphones and smart home devices to innovative gadgets and accessories, find detailed reviews, buying guides, and expert recommendations. Stay updated with trends and make informed choices for your tech needs. Explore our collection and elevate your tech experience today!', 167);
INSERT INTO `categories` (`id`, `wp_term_id`, `wp_taxonomy_id`, `name`, `slug`, `parent_id`, `description`, `count`) VALUES (3, 63, 63, 'Books', 'books', 0, 'Discover the perfect book for every reader in our extensive book selection. From bestsellers and classics to niche genres and hidden gems, we curate a diverse collection to satisfy your literary cravings. Explore in-depth reviews, recommendations, and reading guides to help you find your next favorite book. Dive into the world of literature and start your reading journey today!', 183);
INSERT INTO `categories` (`id`, `wp_term_id`, `wp_taxonomy_id`, `name`, `slug`, `parent_id`, `description`, `count`) VALUES (4, 64, 64, 'Blog', 'blog', 0, 'Unlock a world of knowledge with our engaging blog, featuring insights, tips, and trends across various topics. From health and beauty to tech and lifestyle, we provide valuable content to inspire and inform. Stay updated with expert advice and practical guides that enhance your everyday life. Dive into our latest posts and discover something new today!', 85);
INSERT INTO `categories` (`id`, `wp_term_id`, `wp_taxonomy_id`, `name`, `slug`, `parent_id`, `description`, `count`) VALUES (5, 103, 103, 'Fashion', 'fashion', 0, 'Stay ahead of the trends with our fashion insights, featuring the latest styles, must-have outfits, and expert tips. Explore top fashion brands, seasonal collections, and timeless wardrobe essentials that elevate your look. Whether it\'s casual wear, formal attire, or accessories, discover how to perfect your style with our curated fashion guides. Refresh your wardrobe and stay stylish today!', 18);
INSERT INTO `categories` (`id`, `wp_term_id`, `wp_taxonomy_id`, `name`, `slug`, `parent_id`, `description`, `count`) VALUES (6, 112, 112, 'Baby Products', 'baby-products', 0, 'Explore our range of high-quality baby products designed for safety, comfort, and convenience. From gentle skincare and feeding essentials to cozy bedding and playful toys, we offer everything you need to nurture your little one. Discover expert reviews, buying guides, and tips for new parents to make informed choices for your baby\'s health and happiness. Shop now for the best in baby care!', 21);
INSERT INTO `categories` (`id`, `wp_term_id`, `wp_taxonomy_id`, `name`, `slug`, `parent_id`, `description`, `count`) VALUES (7, 119, 119, 'Decoration', 'decoration', 0, 'Transform your space with our stunning decoration ideas and products. From stylish home decor and seasonal accents to unique furnishings and art pieces, we offer inspiration to enhance any room. Explore expert tips, trends, and DIY projects to create a personalized and inviting atmosphere. Elevate your home’s aesthetic and express your style with our curated collection today!', 7);
INSERT INTO `categories` (`id`, `wp_term_id`, `wp_taxonomy_id`, `name`, `slug`, `parent_id`, `description`, `count`) VALUES (8, 225, 225, 'Health and Wellness', 'health-and-wellness', 0, 'Explore expert tips and advice on health and wellness, from fitness routines and nutrition to mental well-being and self-care. Discover natural remedies, healthy recipes, and lifestyle changes to improve your overall health. Stay informed with our guides on achieving balance and vitality for a happier, healthier life. Start your wellness journey today!', 27);
INSERT INTO `categories` (`id`, `wp_term_id`, `wp_taxonomy_id`, `name`, `slug`, `parent_id`, `description`, `count`) VALUES (9, 233, 233, 'Politics', 'politics', 0, 'Stay informed with the latest updates and insights on politics. Explore in-depth analysis, news, and opinions on global and national political events, policies, and leaders. From elections to policy changes, our expert coverage keeps you engaged and aware of the political landscape. Stay updated on the issues that matter most in the world of politics today!', 10);
INSERT INTO `categories` (`id`, `wp_term_id`, `wp_taxonomy_id`, `name`, `slug`, `parent_id`, `description`, `count`) VALUES (10, 234, 234, 'Travel', 'travel', 0, 'Explore the best travel destinations, tips, and guides in our Travel category. Discover top vacation spots, hidden gems, and essential travel advice for your next adventure.', 11);
INSERT INTO `categories` (`id`, `wp_term_id`, `wp_taxonomy_id`, `name`, `slug`, `parent_id`, `description`, `count`) VALUES (11, 235, 235, 'Sports', 'sports', 0, 'Stay updated with the latest sports news, scores, and highlights from around the world. Explore in-depth coverage of major leagues, tournaments, and athletes across football, basketball, cricket, and more. Get expert analysis, game reviews, and exclusive insights into your favorite sports and teams. Follow the action and never miss a moment with our comprehensive sports coverage!', 6);
INSERT INTO `categories` (`id`, `wp_term_id`, `wp_taxonomy_id`, `name`, `slug`, `parent_id`, `description`, `count`) VALUES (12, 377, 377, 'Sera 10 Lists', 'sera-10-lists', 0, 'Discover Top10, your go-to blog site for diverse insights across categories like Tech Products, Beauty, Baby Care, Fashion, Health & Wellness, Food Recipes, Entertainment, Politics, Sports, and more. Explore expert tips, in-depth reviews, and engaging articles that inspire and inform. Stay updated with the latest trends, news, and lifestyle content curated for all your interests.', 162);
INSERT INTO `categories` (`id`, `wp_term_id`, `wp_taxonomy_id`, `name`, `slug`, `parent_id`, `description`, `count`) VALUES (13, 407, 407, 'Food', 'food', 0, 'Discover a world of flavors with our diverse collection of food and recipes. From quick and easy meals to gourmet dishes, explore step-by-step guides, expert cooking tips, and delicious recipes for every occasion. Whether you\'re a beginner or a seasoned chef, find inspiration for breakfast, lunch, dinner, and desserts. Elevate your culinary skills and enjoy mouth-watering meals today!', 6);
INSERT INTO `categories` (`id`, `wp_term_id`, `wp_taxonomy_id`, `name`, `slug`, `parent_id`, `description`, `count`) VALUES (14, 865, 865, 'Entertainment', 'entertainment', 0, 'Dive into the world of entertainment with our comprehensive guide to movies, TV shows, music, and more. Discover the latest releases, reviews, and trends in pop culture, and explore engaging articles that keep you informed and entertained. Whether you\'re looking for binge-worthy series or must-see films, find all your entertainment needs in one place. Join us for the latest updates and insights today!', 6);
INSERT INTO `categories` (`id`, `wp_term_id`, `wp_taxonomy_id`, `name`, `slug`, `parent_id`, `description`, `count`) VALUES (15, 1094, 1094, 'Beauty and Personal Care', 'beauty-and-personal-care', 0, 'Discover your ultimate beauty destination with our curated selection of skincare, makeup, and grooming products. From nourishing creams and serums to vibrant cosmetics, we offer top-quality brands to enhance your natural beauty. Explore expert reviews, tips, and trends to elevate your beauty routine. Shop now for a radiant, confident you!', 39);
